#!/usr/bin/env bash
# Collect subscription usage for grok, codex, claude, antigravity, muse, grok-bot into /workspace/token-usage/raw/
export PATH=$HOME/.local/bin:$PATH
S=/workspace/agent-scripts; R=/workspace/token-usage/raw; ts=$(date +%Y-%m-%d_%H%M); now=$(date -Iseconds)
N='input_tokens:null,output_tokens:null,total_tokens:null,cost_usd:null'
run(){ name=$1; shift; out=$R/${ts}_$name.jsonl; if "$@" > $out.tmp 2>$out.err && [ -s $out.tmp ]; then mv $out.tmp $out; rm -f $out.err; echo "OK $out"; else rm -f $out.tmp; echo "FAIL $name: $(head -c 300 $out.err)"; rm -f $out.err; fi; }
grok(){ { $S/grok-billing.sh 2>/dev/null || { (cd /tmp && timeout 90 grok --single hi --model "Grok 4.5" --reasoning-effort low >/dev/null 2>&1); $S/grok-billing.sh; }; } | jq -c --arg now "$now" ".config | {collected_at:\$now,service:\"grok\",model:\"GrokBuild\",period_start:.currentPeriod.start,period_end:.currentPeriod.end,$N,used_percent:.creditUsagePercent,limit_type:\"weekly\",reset_at:.currentPeriod.end,source:\"grok-billing.sh\"}"; }
codex(){ timeout 60 python3 $S/codex-account-rateLimits-read.py | jq -c --arg now "$now" ".rateLimits as \$r | \$r.primary.resetsAt as \$e | {collected_at:\$now,service:\"codex\",model:(\"ChatGPT \"+\$r.planType),period_start:((\$e-\$r.primary.windowDurationMins*60)|todate),period_end:(\$e|todate),$N,used_percent:\$r.primary.usedPercent,limit_type:\"weekly\",reset_at:(\$e|todate),source:\"codex-account-rateLimits-read.py\"}"; }
claude(){ { $S/claude-usage.sh 2>/dev/null || { (cd /tmp && timeout 90 claude -p hi >/dev/null 2>&1); $S/claude-usage.sh; }; } | jq -c --arg now "$now" ".limits[] | {collected_at:\$now,service:\"claude\",model:(.scope.model.display_name // .scope.model.id // (if .kind==\"weekly_scoped\" then \"scoped\" else \"all models\" end)),period_start:null,period_end:.resets_at,$N,used_percent:.percent,limit_type:.kind,reset_at:.resets_at,source:\"claude-usage.sh\"}"; }
agy(){ timeout 90 $S/agy-print-usage.sh --output-format-json | jq -c --arg now "$now" ".command.data.groups[] as \$g | \$g.buckets[] | {collected_at:\$now,service:\"antigravity\",model:\$g.name,period_start:null,period_end:.reset_time,$N,remaining_percent:((.remaining_fraction*1000|round)/10),limit_type:(.window // \"weekly\"),reset_at:.reset_time,source:\"agy-print-usage.sh\"}"; }
muse(){ (cd /tmp && timeout 120 muse exec hi --model muse-ember-1.0 --effort minimal >/dev/null 2>&1); $S/muse-usage.sh --json | jq -c --arg now "$now" ".allowance | select(.!=null) | .tier as \$t | [\"weekly\",\"window\"][] as \$k | select(.[\$k]!=null) | {collected_at:\$now,service:\"muse\",model:\$t,period_start:null,period_end:(.[\$k].resetsAtMs/1000|todate),$N,used_percent:.[\$k].usedPercent,limit_type:\$k,reset_at:(.[\$k].resetsAtMs/1000|todate),source:\"muse-usage.sh\"}"; }
grokbot(){ local T; T=$($S/grok-bot-cursor-token-from-linux.sh) || return 1; GROK_BOT_ACCESS_TOKEN="$T" timeout 60 $S/grok-bot-cursor-usage.sh | jq -c --arg now "$now" "{collected_at:\$now,service:\"grok-bot\",model:(.grokPlanLabel // .includedUsageSuperGrokPlan),period_start:.currentPeriodStart,period_end:.nextResetTimestampUtc,$N,used_percent:((.usagePercent*100|round)/100),limit_type:\"weekly\",reset_at:.nextResetTimestampUtc,source:\"grok-bot-cursor-usage.sh\"}"; }
run grok grok; run codex codex; run claude claude; run antigravity agy; run muse muse; run grok-bot grokbot
